// Procesar mensajes de Telegram: texto normal o documento PDF
const https = require('https');
const message = $input.item.json.message;

// Caso 1: Mensaje de texto normal
if (message.text) {
  return { message };
}

// Funcion para hacer GET con https nativo
function httpsGet(url) {
  return new Promise((resolve, reject) => {
    https.get(url, (res) => {
      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => resolve(Buffer.concat(chunks)));
      res.on('error', reject);
    }).on('error', reject);
  });
}

// Caso 2: Mensaje con documento PDF (CFDI)
if (message.document && message.document.mime_type === 'application/pdf') {
  // IMPORTANTE: Reemplaza con tu Bot Token de Telegram
  const BOT_TOKEN = '8703916390:AAFZSEQYhvyn0HMxP_UMlQU-0uZTR4VBkj0';

  try {
    // Obtener ruta del archivo en Telegram
    const fileInfoBuf = await httpsGet(
      `https://api.telegram.org/bot${BOT_TOKEN}/getFile?file_id=${message.document.file_id}`
    );
    const fileInfo = JSON.parse(fileInfoBuf.toString());
    if (!fileInfo.ok) throw new Error('No se pudo obtener info del archivo');
    const filePath = fileInfo.result.file_path;

    // Descargar el archivo PDF
    const pdfBuffer = await httpsGet(
      `https://api.telegram.org/file/bot${BOT_TOKEN}/${filePath}`
    );

    // Extraer texto del PDF
    let textoExtraido = '';
    try {
      const pdfParse = require('pdf-parse');
      const pdfData = await pdfParse(pdfBuffer);
      textoExtraido = pdfData.text;
    } catch (e) {
      // Fallback: extraccion basica de strings del PDF
      const raw = pdfBuffer.toString('latin1');
      const matches = raw.match(/\(([^)]+)\)/g);
      if (matches && matches.length > 5) {
        textoExtraido = matches.map(m => m.slice(1, -1)).join(' ');
      }
      if (!textoExtraido || textoExtraido.length < 30) {
        textoExtraido = '[PDF recibido: ' + message.document.file_name + '. No se pudo extraer texto. Para habilitar lectura de PDF instala pdf-parse y configura NODE_FUNCTION_ALLOW_EXTERNAL=pdf-parse en n8n.]';
      }
    }

    const caption = message.caption ? '\nMensaje del operador: ' + message.caption : '';
    return {
      message: {
        ...message,
        text: '[DOCUMENTO PDF RECIBIDO: ' + message.document.file_name + ']' + caption + '\n\nContenido extraido del CFDI:\n---\n' + textoExtraido + '\n---\nProcesa esta informacion segun el proceso de facturacion correspondiente (Proceso 6 o 7).'
      }
    };
  } catch (error) {
    return {
      message: {
        ...message,
        text: 'El operador envio un PDF (' + message.document.file_name + ') pero hubo error: ' + error.message + '. Solicita al operador que envie los datos del CFDI manualmente.'
      }
    };
  }
}

// Caso 3: Otros tipos de mensaje
const texto = message.caption || '[Mensaje sin texto - solicita al operador que escriba su consulta]';
return { message: { ...message, text: texto } };
